True def transform(grid):
    n, m = len(grid), len(grid[0])
    if n != m:
        raise ValueError("expected a square grid")
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                orbit = {(r,c), (c,r), (r,n-1-c), (n-1-r,c),
                         (n-1-r,n-1-c), (c,n-1-r), (n-1-c,r),
                         (n-1-c,n-1-r)}
                vals = [grid[a][b] for a,b in orbit if grid[a][b] != 2]
                if not vals or any(v != vals[0] for v in vals):
                    raise ValueError("cannot infer occluded cell consistently")
                out[r][c] = vals[0]
    return out
